// The gun audio play queue (app/src/play-queue.js, ARCH-3) against its case file, fixtures/play-queue-cases.json. The
// file is GENERATED by fixtures/gen-play-queue-cases.mjs; this checks it against a fresh run, so a change to the
// queue's behaviour shows up as a stale file. The bench stage is to run the same file (mcp/brx_mcp/stage/stage.py).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { runCase, INPUTS } from './fixtures/gen-play-queue-cases.mjs';
import { PLAY_GAP_MS } from '../src/announcer.js';
import { PLAY_QUEUE_STALE_MS } from '../src/engine.js';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const FIXTURE = JSON.parse(readFileSync(path.join(HERE, 'fixtures', 'play-queue-cases.json'), 'utf8'));

test('play-queue cases: the file has every case the generator has, and the constants the code has', () => {
  assert.deepEqual(FIXTURE.cases.map(c => c.name), INPUTS.map(c => c.name), 'stale file: run `node test/fixtures/gen-play-queue-cases.mjs`');
  assert.equal(FIXTURE.gap_ms, PLAY_GAP_MS);
  assert.equal(FIXTURE.stale_ms, PLAY_QUEUE_STALE_MS);
});

for (const c of FIXTURE.cases) {
  test(`play-queue cases: ${c.name}`, () => {
    const { expect, ...input } = c;
    assert.deepEqual(runCase(input, FIXTURE.clip_ms), expect, 'a fresh run differs from the file: the behaviour changed (or regenerate it on purpose)');
    // `sendAt` agrees with the send: a job's first plan is when it went, unless something after it was queued changed
    // the queue ahead of it (a must-hear write, a hit sound, a cancel), or the case names a known gap.
    for (const j of expect.jobs) {
      if (j.planned == null || j.sent == null || c.plan_differs) continue;
      const moved = c.events.some(e => e.t > j.queued_t && e.t < j.sent && (e.must_hear || e.hit || e.cancel));
      if (!moved) assert.equal(j.planned, j.sent, `${j.job}: planned for ${j.planned}, sent at ${j.sent}`);
    }
  });
}

test('play-queue cases: the known gap is real (the control for `plan_differs`)', () => {
  const c = FIXTURE.cases.find(x => x.plan_differs);
  assert.ok(c, 'one case pins the gap');
  assert.ok(c.expect.jobs.some(j => j.planned != null && j.sent != null && j.planned !== j.sent), 'its plan and its send differ');
});
